import * as THREE from 'three/webgpu';
import * as TSL from 'three/tsl';

export default function createNode(config, ctx) {
  const colors = config.colors || {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const container = new THREE.Group();
  container.position.set(-3.2, 1, 0.06);

  // Load sprite texture
  const texture = ctx.textureLoader.load('/prism-mock/home/nodes/floating-accent.png');
  texture.colorSpace = THREE.SRGBColorSpace;

  // Create plane geometry with 1.6:1 aspect ratio (512×320)
  const geometry = new THREE.PlaneGeometry(1.6, 1);

  // Create TSL-based material
  const colorNode = TSL.texture(texture);
  const material = new THREE.MeshBasicNodeMaterial({
    colorNode,
    transparent: true,
  });

  // Create sprite mesh
  const mesh = new THREE.Mesh(geometry, material);
  mesh.rotation.y = Math.PI;
  container.add(mesh);

  // Render text content via fontAtlas
  let textMesh = null;
  const textContent = config.textContent || 'Collection 1';
  textMesh = ctx.fontAtlas.render(textContent, {
    font: 'Lora',
    size: 0.34,
    weight: 400,
    color: colors.ink,
  });

  if (textMesh) {
    textMesh.position.z = 0.1;
    container.add(textMesh);
  }

  // Billboard effect: update each frame to face camera
  container.userData.update = (camera) => {
    mesh.lookAt(camera.position);
  };

  // Resource cleanup
  container.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
    if (textMesh?.geometry) textMesh.geometry.dispose();
    if (textMesh?.material) textMesh.material.dispose();
  };

  container.userData.handlers = {};

  return container;
}
